package glitch

import data.glitch_lib

# Unencrypted protocols
unencrypted_protocols := {"http://", "ftp://", "telnet://", "ldap://", "smtp://"}

# Weak TLS/SSL versions
weak_tls_versions := {"TLSv1.0", "TLSv1.1", "SSLv2", "SSLv3", "1.0", "1.1", "ssl3"}

# Encryption enforcement attributes
encryption_enforcement_attrs := {"https_only", "secure_transfer", "require_https", "enforce_tls", "tls_required", "ssl_required", "minimum_tls_version", "enable_https_traffic_only", "enforce_ssl", "require_secure_transport"}

# Sensitive data indicators
sensitive_data_attrs := {"password", "secret", "token", "credential", "api_key", "access_key", "session", "cookie", "auth_token", "ssn", "email", "phone", "credit_card", "payment"}

# Public exposure indicators
public_exposure_attrs := {"public_access", "public", "exposed", "public_network_access", "public_endpoint", "external_endpoint"}

# Disabled/insecure values
disabled_values := {"false", "off", "no", "disabled", "0", 0, false}

# Helper to check if value contains unencrypted protocol
has_unencrypted_protocol(value) {
    value.ir_type == "String"
    proto := unencrypted_protocols[_]
    startswith(lower(value.value), proto)
}

# Helper to check if value is a weak TLS version
is_weak_tls_version(value) {
    value.ir_type == "String"
    ver := weak_tls_versions[_]
    contains(lower(value.value), lower(ver))
}

# Helper to check if value indicates disabled security
is_security_disabled(value) {
    value.ir_type == "String"
    val := disabled_values[_]
    is_string(val)
    lower(value.value) == val
} else {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Helper to collect all nested values from complex types
collect_nested_values(node) = values {
    node.ir_type == "String"
    values := {node.value}
} else = values {
    node.ir_type == "Boolean"
    values := {node.value}
} else = values {
    node.ir_type == "Integer"
    values := {node.value}
} else = values {
    node.ir_type == "VariableReference"
    values := {node.value}
} else = values {
    node.ir_type == "Hash"
    values := {v | some k, v; node.value[k].ir_type == "String"; v := node.value[k].value}
} else = values {
    node.ir_type == "Array"
    values := {v | some i; node.value[i].ir_type == "String"; v := node.value[i].value}
} else = values {
    values := set()
}

# Check for sensitive data in attributes
has_sensitive_data_attribute(attrs) {
    attr := attrs[_]
    sens := sensitive_data_attrs[_]
    contains(lower(attr.name), sens)
}

# Check for public exposure in attributes
has_public_exposure(attrs) {
    attr := attrs[_]
    pub := public_exposure_attrs[_]
    contains(lower(attr.name), pub)
    not is_security_disabled(attr.value)
}

# Check for unencrypted endpoint or protocol
has_unencrypted_endpoint(attrs) {
    attr := attrs[_]
    attr.value.ir_type == "String"
    has_unencrypted_protocol(attr.value)
}

# Check for weak TLS version configuration
has_weak_tls_version(attrs) {
    attr := attrs[_]
    contains(lower(attr.name), "tls_version")
    is_weak_tls_version(attr.value)
} else {
    attr := attrs[_]
    contains(lower(attr.name), "ssl_version")
    is_weak_tls_version(attr.value)
}

# Check for disabled encryption enforcement
has_disabled_encryption_enforcement(attrs) {
    attr := attrs[_]
    enc := encryption_enforcement_attrs[_]
    contains(lower(attr.name), enc)
    is_security_disabled(attr.value)
}

# Missing encryption enforcement when public
missing_encryption_when_public(attrs) {
    has_public_exposure(attrs)
    not has_encryption_enforcement(attrs)
}

# Check if any encryption enforcement exists
has_encryption_enforcement(attrs) {
    attr := attrs[_]
    enc := encryption_enforcement_attrs[_]
    contains(lower(attr.name), enc)
    not is_security_disabled(attr.value)
}

# Scenario 1: Sensitive data + unencrypted transport
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    count(attrs) > 0

    # Has sensitive data attribute
    has_sensitive_data_attribute(attrs)

    # Has unencrypted endpoint/protocol
    has_unencrypted_endpoint(attrs)

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Sensitive data may be transmitted over unencrypted channels. (CWE-319)"
    }
}

# Scenario 2: Public exposure + missing or disabled encryption
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    count(attrs) > 0

    # Publicly exposed
    has_public_exposure(attrs)

    # Missing encryption enforcement
    missing_encryption_when_public(attrs)

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Publicly exposed resource lacks encryption enforcement. (CWE-319)"
    }
}

# Scenario 3: Weak TLS/SSL version configured
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    count(attrs) > 0

    has_weak_tls_version(attrs)

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Weak or deprecated TLS/SSL version configured. (CWE-319)"
    }
}

# Scenario 4: Explicitly disabled encryption enforcement
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
