is_disabled_value(node) {
    node.ir_type == "Boolean"
    node.value == false
} else {
    node.ir_type == "String"
    lower(node.value) == disable_values[_]
} else {
    node.ir_type == "Integer"
    node.value == 0
}

is_weak_tls_version(node) {
    node.ir_type == "String"
    val := lower(node.value)
    val == weak_tls_versions[_]
